pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover residual (oracle minimizes score).
    let mut score = pr;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: next item filling post_residual exactly is nearly as good.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr;
            // Stronger reward late in the stream, when future reuse matters most.
            score -= (120.0 + 120.0 * progress) * fill;
        } else {
            // Next item cannot use the leftover: penalize the unusable gap.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Super-linear progress coupling: late waste is heavily punished.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * pr * norm_pr * norm_pr;

    // Keep residual distribution tight vs. the fleet mean (reusability).
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0 * (0.5 + 0.5 * progress);
    }

    // Dead-space penalty: fragments below plausible minimum item size.
    if pr > 0.0 && pr < 10.0 {
        score += 80.0 + 20.0 * progress;
    }

    // New-bin candidate logic: penalize opening bins, more so late / when many open.
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);
        // Early on, a fresh bin is acceptable if it promises low waste.
        score -= 25.0 * (1.0 - progress) * (1.0 - norm_pr);
        // If next item is large and no open bin looks promising, opening is fine.
        if next_item_size as f64 > cap * 0.5 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste — penalize heavily.
    if post_residual < 10 {
