        if post_residual >= next_item_size && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and open-bin pressure is high.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // Large items fit poorly in partially filled bins; opening a fresh bin
        // for them is more attractive.
        score -= (item_size as f64 / 100.0) * 30.0;
    }

    // Open-bins pressure: many open bins means scattered residuals; mild
    // reward for consolidating into bins with small residual (tight fits).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Stream progression: late in the stream, avoid leaving awkward gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
