    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: keep it competitive only when open bins fit poorly
    if bin_residual == bin_capacity {
        // Mild penalty so new bins only win when lookahead/dead-space terms dominate
        score += 5.0;
        // Early stream: opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into existing ones
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via modulo classes
    let pr = post_residual;
    // Class 0: post_residual divisible by small harmonics (10, 20, 25, 50) => reusable
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
