            score -= 8.0;
        }
        if pr % 25 == 0 || pr % 50 == 0 {
            score -= 6.0;
        }
        // awkward residues get penalized
        let awkward = pr % 10;
        score += (awkward as f64) * 0.5;

        // Integer-division thresholds: how many items of the *next* size fit
        if next_item_size > 0 && next_item_size <= pr {
            let fits_next = pr / next_item_size;
            score -= (fits_next.min(4) as f64) * 6.0;
        } else if next_item_size > 0 {
