            score += (next_item_size as f64) * 0.15;
        }
    }

    // Capacity fraction classes of the fill level
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill >= 0.75 {
        score -= 12.0; // prefer filling bins past 3/4
    } else if fill >= 0.5 {
        score -= 5.0;
    } else if fill >= 0.25 {
        score += 2.0;
    } else {
        score += 6.0; // avoid scattering into nearly-empty bins
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead = post_residual as f64;
        // opening a new bin is good if the best existing option leaves > 30 dead space
        score = 40.0 + dead * 0.2 - progress * 5.0 - (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // next item similar size: fresh bin useful
        }
    }

    // Mild preference to keep mean residual balanced
    score += ((mean_residual - post_residual as f64).abs()) * 0.1;

    score
}

