    // Crowding: with many open bins, prefer consolidating into existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Prefer bins below mean residual (consolidate emptier bins first)
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.4;
    } else {
        score += (resid_f - mean_residual) * 0.2;
    }

    // New-bin candidate logic: empty bin is a fallback; make it costly unless
    // the fit into open bins would be very poor or no bins fit
    if bin_residual == bin_capacity {
        let base_penalty = 70.0;
        // Early stream: opening bins is cheap and useful for future flexibility
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let early_benefit = (1.0 - progress) * 30.0;
        score += base_penalty - early_benefit;
        // If nothing fits, new bin must look attractive
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late stream: avoid opening new bins, squeeze tighter
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score += 25.0 * (progress - 0.7) / 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits but tolerate larger residuals.
    // Late in stream: heavily penalize any wasted residual.
    let progress_weight = 0.5 + 1.5 * progress * progress;

    let mut score = pr * (1.0 + progress_weight * norm_pr * norm_pr);

    // Quadratic smooth interaction: residual penalty grows super-linearly
    // as stream progresses, favoring near-perfect packing late.
    score += 40.0 * progress * norm_pr * norm_pr * cap.sqrt();

    // Slight reward for leaving residual close to a plausible next-item size.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - diff / cap).max(0.0) * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.3 + 0.7 * progress);
    }

    // Mild penalty for opening new bins when many bins are already open late.
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);
        // But allow opening a new bin early with small residual waste potential.
        score -= 20.0 * (1.0 - progress) * (1.0 - norm_pr);
    }

    // Dead-space penalty: residuals too small to fit any plausible item.
    if pr > 0.0 && pr < 10.0 {
        score += 30.0 * (10.0 - pr) * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // fraction of capacity left over

    // Dead-space penalty: leftovers that are too small to host typical items are bad.
    if post_residual == 0 {
        score -= 60.0; // perfect fill: strongly reward
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if frac <= 0.2 {
        score += 8.0; // small leftover, mildly wasteful
    } else if frac <= 0.4 {
        score -= 4.0; // sweet spot: leaves room for medium items
    } else if frac <= 0.6 {
        score -= 2.0;
    } else {
        score += 3.0; // leaving more than 60% free means a poor fit
    }

    // Integer-division thresholds on post_residual: leftovers divisible into
    // common item classes (10/20/25/50) are more reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if reusable {
        score -= 6.0;
    }

    // Lookahead coupling: reward if next_item_size fits exactly in the leftover,
    // penalize if it fits poorly (leaving a sliver after the next item).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // guaranteed perfect follow-up fill
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 5 {
                score -= 20.0; // near-perfect chain fill
            } else if next_post < 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin anyway; slight penalty for hoarding space
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (mean_residual - item_size as f64) < 15.0;
        if tight_exists {
            score += 20.0; // keep using existing bins
        } else {
            score -= 5.0; // fresh bin is reasonable
        }
    }

    // Mild pressure to prefer bins below the mean residual (tightest-first bias).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Progress-aware scaling: early in the stream, be more tolerant of leftovers.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (or for the known next item) are nearly unusable.
    let min_item = 1u32;
    let dead_threshold = next_item_size.max(min_item);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // hard penalty: created an unusable gap
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Reward exact fit of the lookahead item (two-item chain completion).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Penalize leaving gaps in the awkward mid-range (hard to fill later).
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or
    // the fit here would be very poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0 + mean_residual / 8.0;
        score += 90.0 - pressure;
        // Discourage opening bins early in the stream.
        score += 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Open-bin pressure: mildly discourage accumulating many open bins
    // when the fit is loose.
    score += open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (good packing discipline).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * fill;
        } else {
            // Next item cannot use the leftover: penalize dead space relative to next item size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid creating below-average waste
    // relative to other bins (keeps residual distribution tight and reusable).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize small unusable fragments (< 10, minimum item size) — true dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Late in the stream, prefer closing bins tightly (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // Mild preference for keeping the number of open bins low when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let min_item = 1.0f64;
        let dead = (post_residual as f64).max(min_item);
        if dead < 15.0 {
            score += (15.0 - dead) * 1.8; // tiny slivers are wasted space
        }
    }

    // Lookahead coupling: if the next item fits perfectly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack);
        } else {
            // next item won't fit here; mild penalty scaled by how close we were
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    } else {
        // last item: prefer minimal final residual
        score -= 5.0;
    }

    // Last-chance bin logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.3 {
            score -= 25.0 * fit_quality;
        }
    }

    // New-bin candidate handling: an empty bin is a long-term investment.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let open_cost = 8.0 + 30.0 * progress;
        // Penalize new bins more when many bins are already open with slack.
        let slack_pressure = (mean_residual / bin_capacity as f64) * open_bins_count as f64;
        score = open_cost + slack_pressure * 4.0 + item_size as f64 * 0.1;
    }

    // Prefer bins with residual close to the mean (keeps a balanced portfolio),
    // except when the item nearly fills the bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if post_residual > 0 {
        score += dev * 0.05;
    } else {
        score -= dev * 0.02; // perfect fills are good regardless of balance
    }

    // Mild time-horizon effect: as the stream ends, exact fills matter more.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= horizon * (100.0 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic coupling of post-residual with stream progress.
    // Early on (progress ~ 0): prefer tight fills (penalize large residual quadratically).
    // Late (progress ~ 1): residual waste matters less than keeping bins open.
    let mut score = x * x * (1.0 + 2.0 * (1.0 - progress)) * 100.0
                  + x * (1.0 - progress) * 30.0;

    // Smooth cubic interaction: residual vs mean residual divergence.
    // Penalize bins whose post residual deviates strongly below mean (isolating waste).
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * dev.abs() * 50.0 * (0.5 + progress);

    // Perfect fit reward (smooth, non-piecewise): strong subtraction near x ~ 0.
    score -= 60.0 * (-x * 8.0).exp();

    // Last-chance bonus: if this is the only fitting bin, reward using it smoothly.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress) + 10.0;
    }

    // Lookahead coupling: reward residual that still accommodates next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (x * cap - nx).max(0.0) / cap;
        score -= 20.0 * (fits_next / (fits_next + 0.05));
    }

    // Mild pressure to prefer existing bins over opening new ones as bins accumulate.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic classes: classify post_residual into capacity fraction buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual as u32;

    // Dead-space penalty grows superlinearly for residuals that no typical
    // item (1..=100) can usefully fill; tiny slivers are worthless.
    if post > 0 && post < 10 {
        score += 40.0;
    } else if post < eighth {
        score += 12.0;
    } else if post < quarter {
        score -= 4.0; // quarter-class residual is highly reusable
    }

    // Modulo arithmetic: residuals that are multiples of small classes
    // (16/32/50) tile well with common item sizes; reward them.
    let r = post as i64;
    let mut harmonic_bonus = 0.0;
    if r % 16 == 0 && r > 0 { harmonic_bonus += 6.0; }
    if r % 32 == 0 && r > 0 { harmonic_bonus += 6.0; }
    if r % 50 == 0 && r > 0 { harmonic_bonus += 8.0; }
    if r % 25 == 0 && r > 0 { harmonic_bonus += 3.0; }
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual (perfect harmonic pair), strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            // next item fits: penalize by how much slack would remain after it
            let after_next = post - next_item_size;
            if after_next < 10 { score += 8.0; } else { score -= 6.0; }
        } else {
            // next item won't fit here; residual becomes dead unless reusable
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post >= 0 {
        score -= 15.0;
        if post < 10 { score += 10.0; } // unless it creates a sliver
    }

    // New-bin candidate: opening a new bin is only attractive when the
    // item is large relative to capacity and open bins are all cramped.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        let new_bin_score = cap - item_size as f64; // residual of fresh bin
        // Base cost of a new bin: high unless item is big or bins are tight.
        let avg_open = if open_bins_count > 0 { mean_residual } else { cap };
        let cramped = avg_open < item_size as f64 * 1.2;
        let penalty = if item_frac > 0.6 || cramped {
            new_bin_score - 20.0
        } else {
            new_bin_score + 35.0 + 20.0 * progress
        };
        score = penalty;
    }

    // Slight preference for tighter bins overall (waste-minimizing tiebreak).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // gap sizes 1..=12 are "dead" for typical future items (10..80)
        let dead_zone = 12.0;
        if pr <= dead_zone {
            score += (dead_zone - pr + 1.0) * 30.0; // steep penalty inside dead zone
        } else {
            // beyond dead zone, moderate penalty scaled by how far from useful sizes
            score += pr * 0.5;
        }
    } else {
        // perfect fit: strong reward
        score -= 100.0;
    }

    // Reward tight fits generally (post_residual small relative to residual)
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 20.0;
    }

    // Open bins pressure: discourage spreading when many bins already open,
    // but encourage using existing bins over opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor placing here instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and existing residuals are poor. Base penalty for the fresh empty bin.
    if bin_residual == bin_capacity {
        score += 60.0;
        // allow new bin when item is large and mean residual can't host next item well
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 60 && mean_residual < item_size as f64 * 1.1 {
            score -= 80.0;
        }
        // late in stream with many open bins, prefer consolidation
        if progress > 0.7 {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 90.0;
    }
    // If next item would be blocked by post_residual (dead space for lookahead), penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Slight preference for bins below mean residual (balance residuals)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the residual left behind (good chaining)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item would NOT fit: residual becomes dead space
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable residuals relative to mean residual
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.4 {
        score += 12.0;
    }

    // New empty bin candidate: prefer open bins unless they are bad fits
    if bin_residual == bin_capacity {
        let base_penalty = 25.0
            + 5.0 * (open_bins_count as f64).ln().max(0.0)
            + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // If no other bin truly fits well, allow opening a new bin
        if fitting_bins_count == 0 {
            score = -10.0;
        } else if next_item_size > 0 && post_residual == next_item_size {
            score = 5.0; // still allow fresh bin if it sets up next item perfectly
        } else {
            score = base_penalty + item_size as f64 * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item (~10) is wasted; penalize it extra.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 0.5; // near-perfect fit bonus region
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3; // mild penalty for leaving awkward slack
        } else {
            // next item won't fit here regardless; residual becomes dead
            // space unless it's small enough for future tiny items.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 8.0; // stranded sliver
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the item fits poorly everywhere else. Compare
    // item size against bin_residual tightness of open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, discounted when the stream is
        // early (long horizon ahead, more future items to balance) and
        // when open bins are already crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 35.0 + 20.0 * progress;
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_cost += 15.0; // plenty of space exists elsewhere
        }
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // must open
        }
        score += new_bin_cost;
        // Large items prefer fresh bins (avoid fragmentation).
        if item_size > 60 {
            score -= 12.0;
        }
    } else {
        // Fragmentation pressure: penalize placing into bins whose
        // residual is far above the item (wasteful big-gap fills) but
        // reward using bins whose residual is close to the item.
        let gap = (bin_residual - item_size) as f64;
        score += gap * 0.1;
        // Prefer spreading across many open bins when mean residual is high.
        if mean_residual > 50.0 && gap > 30.0 {
            score += 5.0;
        }
    }

    // Global balance: nudge toward bins below mean residual to keep the
    // bin population even, which preserves mid-size residual slots.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Late-stream: consolidate aggressively to close out bins.
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: post residual, non-linearly penalized (dead space grows quadratically).
    let mut score = pr + 0.9 * pr * pr / cap;

    // Reward tight fits: coupling of fill ratio with post-residual.
    score -= 18.0 * fit * fit * (1.0 - pr / cap);

    // Stream-progress coupling: early on, prefer leaving flexible residuals;
    // late, prefer aggressive filling (amplify dead-space penalty over time).
    score += pr * (0.6 + 1.4 * progress) * 0.5;

    // Lookahead: if next item fits the post-residual, reward this bin strongly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 12.0 * (next_item_size as f64 / pr);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bonus: only one bin fits — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate when other bins fit, scaled by progress.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress + 2.0 * open_bins_count as f64 * 0.5;
    }

    // Mild penalty when this bin's residual is far from mean residual (imbalance).
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual divisible-by-10 classes; small dead space is bad
    let post_class = post_residual % 10;
    if post_class > 0 && post_class < 5 {
        score += 25.0; // tiny unusable slivers
    }

    // Integer-division thresholds on post_residual
    let post_quarter = post_residual / (bin_capacity / 4);
    score += 15.0 * (4 - post_quarter) as f64;

    // Lookahead: next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = post_residual - next_item_size;
        score -= 40.0 - 0.5 * next_waste as f64;
        // bonus if next item fills post_residual completely
        if next_waste == 0 {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize proportional to leftover
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: only open new bin when residual is huge and current fit is poor
    if bin_residual == bin_capacity {
        if post_residual < 20 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 500.0; // rare: open bin to preserve chain
        } else {
            score += 300.0; // prefer existing bins generally
        }
    }

    // Mean residual coupling: penalize placing into bins already below mean residual
    if (post_residual as f64) < mean_residual {
        score += 10.0;
    }

    // Modulo arithmetic on capacity fraction: prefer post_residual in "harmonic" classes
    let half = bin_capacity / 2;
    if post_residual % half == 0 && post_residual > 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // A gap is "dead" if it is smaller than the smallest plausible item (1)
    // but practically: gaps below ~10-15 waste the bin.
    let dead_threshold = 15.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize large post_residual when the next item cannot use it.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) > post_residual {
            score += (post_residual as f64) * 0.5;
        } else {
            // Reward bins whose leftover accommodates the lookahead item.
            score -= 10.0 + (post_residual - next_item_size as u32) as f64 * 0.2;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing ones rather than opening new bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it is
    // chosen only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    }

    // Mild progression scaling: early on, keep bins flexible (favor tighter fits less aggressively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item also fits in the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly: leftover can host the next item; reward proportional to snugness.
            let snug = (post_residual - next_item_size) as f64;
            score -= 60.0 - snug * 0.5;
        } else {
            // Dead space relative to next item: penalize unusable leftover.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is larger than average (consume slack where it is abundant).
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - resid) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize creating tiny unusable slivers (< 10) that no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Early in the stream, be more willing to open fresh bins (keep flexibility);
    // later, prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 40.0;
        // Don't open a new bin when a perfect/last-chance fit exists elsewhere.
        if post_residual == 0 { score += 900.0; }
        if fitting_bins_count == 1 { score += 200.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect / near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    } else if post_residual < 20 {
        score -= 25.0;
    }

    // Penalize dead space relative to capacity.
    score += 0.4 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        let next_fits_after = post_residual >= next_item_size;
        let next_fits_now_elsewhere = next_item_size <= bin_residual;
        if next_fits_after {
            score -= 15.0;
        } else if next_fits_now_elsewhere {
            // We consume space the next item could have used; penalize proportionally.
            score += 10.0 + 0.2 * next_item_size as f64;
        }
        // If next item exactly matches post residual, big bonus (chain packing).
        if next_item_size == post_residual {
            score -= 50.0;
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when the item is large and fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        let early = progress < 0.3;
        if poor_fit && (early || mean_residual < 0.35 * bin_capacity as f64) {
            score -= 40.0;
        } else {
            score += 30.0 + 50.0 * (1.0 - progress);
        }
        // Large items pack cleanly into fresh bins.
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild time-horizon shaping: later in the stream, be more conservative
    // (favor tight fits even more, discourage waste).
    score += 10.0 * progress * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - progress) * norm_post * norm_post * cap
             + progress * norm_post * cap * (1.0 + norm_item);

    // Penalize large dead space more as stream progresses (less chance to reuse)
    score += 0.8 * poly;

    // Reward tight fits: small post_residual relative to item size
    score -= 12.0 * (1.0 - norm_post).powi(3) * norm_item;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot fit in post_residual
    if next_item_size > 0 && (next_item_size as f64) > post {
        score += 8.0 * ((next_item_size as f64 - post) / cap);
    } else if next_item_size > 0 {
        score -= 4.0 * (1.0 - (next_item_size as f64 - post) / cap);
    }

    // New-bin candidate: discourage unless current residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = 1.0 - mean_residual / cap;
        score += 30.0 * (1.0 - progress) + 10.0 * tightness;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: class 0 = perfectly full.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => -40.0,
        1 | 2 => -12.0,
        3 | 4 | 6 | 7 => 6.0,
        5 => 2.0, // half-empty: reusable, mildly favored
        _ => 10.0, // 8,9: awkward dead space
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: small leftovers are bad.
    if post_residual / 10 == 0 {
        score += 25.0; // post_residual < 10: nearly dead bin
    } else if post_residual / 20 == 0 {
        score -= 5.0; // 10..19: still usable for small items
    }

    // Fraction of capacity consumed: reward tight fills.
    let fill_frac = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill_frac * fill_frac;

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // next item won't fit here; penalize hoarding space it can't use
            score += 8.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when open bins are congested / poor fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 55.0;              // base penalty: prefer reusing open bins
        score -= 30.0 * progress;   // later in stream, fresh bins less costly long-term
        score -= congestion.min(40.0);
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual) {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if this bin is far below average residual, it's a good dump target.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover residual (oracle minimizes score).
    let mut score = pr;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: next item filling post_residual exactly is nearly as good.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / pr;
            // Stronger reward late in the stream, when future reuse matters most.
            score -= (120.0 + 120.0 * progress) * fill;
        } else {
            // Next item cannot use the leftover: penalize the unusable gap.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Super-linear progress coupling: late waste is heavily punished.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * pr * norm_pr * norm_pr;

    // Keep residual distribution tight vs. the fleet mean (reusability).
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin: strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0 * (0.5 + 0.5 * progress);
    }

    // Dead-space penalty: fragments below plausible minimum item size.
    if pr > 0.0 && pr < 10.0 {
        score += 80.0 + 20.0 * progress;
    }

    // New-bin candidate logic: penalize opening bins, more so late / when many open.
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);
        // Early on, a fresh bin is acceptable if it promises low waste.
        score -= 25.0 * (1.0 - progress) * (1.0 - norm_pr);
        // If next item is large and no open bin looks promising, opening is fine.
        if next_item_size as f64 > cap * 0.5 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving zero dead space is ideal.
    if post_residual == 0 {
        score -= 1200.0;
    }

    // 2-step lookahead on the next item.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward by how tightly it fills the remainder,
            // with extra weight for leaving a near-zero second remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            let second_remainder = post_residual - next_item_size;
            let mut bonus = 200.0 * fill;
            if second_remainder < 10 {
                bonus += 120.0; // would create dead fragment after next item
            } else if second_remainder == 0 {
                bonus += 300.0;
            }
            score -= bonus;
        } else {
            // Next item cannot use the leftover: penalize dead space relative to next item size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Compare post_residual against mean residual: keep residual distribution reusable.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize unusable fragments (< 10) — true dead space, scaled by fragment tininess.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 - 8.0 * post_residual as f64;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.3 * post_residual as f64;

    // Mild preference for keeping the number of open bins low when many are open.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: only attractive if current bin leaves a large awkward
    // remainder that the next item cannot use. Otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let waste_now = post_residual as f64; // == capacity for empty bin
        let next_fits_gap = if next_item_size > 0 {
            (next_item_size as f64 - bin_residual as f64).max(0.0)
        } else {
            0.0
        };
        // Empty bin is penalized by capacity; discounted if next item is large
        // relative to open-bin residuals (lookahead escape hatch).
        score += bin_capacity as f64 * 0.9 - next_fits_gap * 0.4;
        let _ = waste_now;
    }

    // Prefer bins whose residual is close to the item (best-fit bias) when many fit.
    if fitting_bins_count > 2 {
        score += 0.15 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain fit is gold; partial fits rewarded by fill ratio.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * fill;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Prefer consuming slack where it is abundant relative to the mean.
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - resid) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Progress-aware new-bin decision: early on keep flexibility, later pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive early and when many bins are open anyway.
        score -= (1.0 - progress) * 40.0;
        // Never open a new bin when a perfect fit or last-chance fit exists.
        if post_residual == 0 { score += 900.0; }
        if fitting_bins_count == 1 { score += 250.0; }
        // If the next item would fit exactly into an existing bin's post_residual elsewhere,
        // discourage opening a fresh bin late in the stream.
        if progress > 0.5 && next_item_size > 0 && post_residual >= next_item_size {
            score += 120.0 * progress;
        }
        // When few bins are open, opening a new one is cheap; when many, prefer reuse.
        score += 0.4 * open_bins_count as f64;
    }

    // Late-stream tightness: waste matters more as we approach the end.
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
