    }

    // Encourage tight fits: reward when the item fills most of the current residual.
    let fill_now = item_size as f64 / bin_residual.max(1) as f64;
    if fill_now > 0.8 {
        score -= 40.0 * (fill_now - 0.8);
    }

    score
}

