    // Lookahead coupling: reward if next item fits exactly or comfortably.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (10.0 - (slack % 10) as f64).abs() * 0.5;
            if slack == 0 {
