    // (the new-bin candidate has bin_residual == bin_capacity, so it gets a large
    // post_residual; we add explicit pressure scaled by open_bins_count).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 18.0 + 2.5 * open_bins_count as f64 + 10.0 * progress;
    } else {
        // Reward using existing bins, more so as open_bins_count grows.
        score -= (open_bins_count as f64).min(20.0) * 0.8;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin and stranding this one's residual.
    if fitting_bins_count == 1 && !new_bin_candidate {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward this placement (sets up a perfect follow-up fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
