    // Penalize if next item would exactly fill post_residual? No — that's great, extra reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item does NOT fit post_residual but this bin could have held more slack.
    if next_item_size > post_residual && post_residual > 0 {
