pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward (strong)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Exact next-item match: chain perfectly
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 640.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            let slack = (post_residual - next_item_size) as f64;
            let mult = if fitting_bins_count > 2 { 240.0 } else { 170.0 };
            score -= mult * fill;
            if slack < 12.0 {
                score -= 40.0 * (1.0 - slack / 12.0);
            }
        } else {
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.85;
        }
    }

    // Harmonic class of post_residual
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    }

    // Dead-space penalty: small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 75.0;
    }

    // Near-dead zone penalties calibrated to capacity fractions
    let quarter = bin_capacity / 4;
    if post_residual > 0 && post_residual < 25 && next_item_size > post_residual {
        score += (25 - post_residual) as f64 * 2.2;
    }
    if post_residual > 0 && next_item_size > post_residual && post_residual < 40 {
        score += (40 - post_residual) as f64 * 1.6;
    }
    if post_residual as f64 >= bin_capacity as f64 * 0.5 {
        score -= 22.0;
    }

    // Divisibility: post_residual can host multiple copies of next item
    if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > next_item_size {
        score -= 55.0;
    }

    // Mean-residual alignment: prefer bins moving residual toward the fleet mean
    score += 0.32 * (post_residual as f64 - mean_residual);

    // Late-stream tight-fit bonus
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    if progress > 0.6 && post_residual > 0 {
        let tight = item_size as f64 / post_residual as f64;
        if tight > 0.8 {
            score -= 22.0 * tight;
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        let usable_waste = post_residual as f64 / bin_capacity as f64;
        score += 45.0 * (1.0 - usable_waste);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if mean_residual < 30.0 {
            score -= 20.0;
        }
        if post_residual > 0 && post_residual < item_size.max(next_item_size) {
            score += 18.0;
        }
    }

    // Mild consolidation pressure scaled by open bins
    score -= open_bins_count as f64 * 0.5;

    // Reusable mid-range residual reward
    if post_residual >= 15 && post_residual <= 60 && next_item_size > 0 {
        score -= 8.0 * (1.0 - ((post_residual as f64 - next_item_size as f64).abs()) / 60.0);
    }

    // Harmonic alignment tie-break
    if (bin_residual as i64 - item_size as i64) % 25 == 0 {
        score -= 10.0;
    }

    score
}

