        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * 0.8;

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate: make empty bins moderately attractive only when
    // existing residuals are poor (high mean residual fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.6 {
            score -= 6.0; // open fresh bin when open bins are fragmented
        } else {
            score += 10.0; // prefer existing bins otherwise
        }
    }

    score
}

