        // opening fresh becomes attractive: reduce penalty as item grows.
        let waste_if_forced = (bin_capacity - item_size) as f64;
        score -= waste_if_forced * 0.15;
        // Early in stream, opening bins is cheap; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins with slack -> avoid adding more.
        if mean_residual > 30.0 && open_bins_count > 3 {
