        if next_item_size as f64 > mean_residual { penalty -= 16.0 ; }
        if post_residual > 0 && post_residual < item_size.max(next_item_size) { penalty += 16.0 ; }
        // Late stream: tolerate new bins less; prefer squeezing existing space.
        if progress > 0.7 { penalty += 8.0 * progress ; }
        score += penalty ;
    }
    // Reward bins whose post-residual stays usable for the following item
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64 ;
        if waste > 0.0 { score += 0.95 * (waste / post_residual as f64) ; }
    }
    // Late-stream: prefer tightest absolute fit more aggressively
    if progress > 0.75 && post_residual > 0 {
        score += 0.17 * post_residual as f64 ;
    }
    // Two-step lookahead: exact chain match strongly favored
    if next_item_size > 0 && post_residual > next_item_size {
        let chain = post_residual - next_item_size ;
        if chain == next_item_size { score -= 100.0 ; }
        else if chain < 8 { score -= 48.0 * (1.0 - chain as f64 / 8.0) ; }
    }
    // Penalize small dead-space residuals, scaled by stream progress
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 3.2 * (0.5 + progress) ;
    }
    // Reward post residuals reusable by mid-size future items
    if post_residual >= 15 && post_residual <= 60 && next_item_size > 0 {
        score -= 9.0 * (1.0 - ((post_residual as f64 - next_item_size as f64).abs()) / 60.0) ;
    }
    // Compaction coupling: when several bins can fit the item, favor the one
    // whose post residual best matches the next item's size class.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs() ;
        if diff < 5.0 { score -= 30.0 * (1.0 - diff / 5.0) ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (<= 10)
    // or too small for the known next item (lookahead k=2).
    if post_residual < 10 {
        score += 60.0; // fully dead space
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // risky narrow window
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + post_residual as f64 * 0.1;
    }

    // Open-bin pressure: penalize spreading across many bins; favor filling existing bins
    // when the item leaves a reusable gap for the next item.
    let open_pressure = open_bins_count as f64 * 1.5;
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= open_pressure;
    } else {
        score += open_pressure * 0.5;
    }

    // Mild trend toward consolidation as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Brand-new empty bin candidate: only attractive when fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

    score
}

