        let nxt = next_item_size as f64;
        if nxt <= pr {
            let waste_after_next = pr - nxt;
            score -= (1.0 - (waste_after_next / cap)) * 8.0;
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * gap * 20.0;
        }
    }

    // Coupling with mean residual: penalize bins far from the mean in a
    // smooth quadratic way (avoid fragmenting the bin population).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: make it attractive only when existing fits are poor
    // (large post_residual) or late in the stream; otherwise discourage.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score = cap * (0.35 + 0.3 * progress) + openness * 3.0 - tightness * 5.0;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
