pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "perfect" fits
    // (0, or tiny unusable slivers are penalized; exact classes near common
    // item sizes 10..80 are favored).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr < 5 {
        score += 40.0; // dead sliver
    } else {
        // Harmonic class: which item-size class could still fit?
        // Classes at multiples of 10 up to 80.
        let class = pr / 10; // 0..=10
        match class {
            0 => score += 35.0,                    // 5..9: nearly dead
            1 => score += 20.0,                    // 10..19: only tiny items
            2 => score += 8.0,                     // 20..29
            3 => score -= 2.0,                     // 30..39
            4 => score -= 6.0,                     // 40..49 sweet zone
            5 => score -= 8.0,                     // 50..59 best zone
            6 => score -= 6.0,                     // 60..69
            7 => score -= 3.0,                     // 70..79
            _ => {}                                // 80+: barely filled bin
        }
        // Fractional coupling: prefer post_residual that is an exact multiple
        // of 10 (harmonic alignment with typical class boundaries).
        if pr % 10 == 0 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how snugly
            score -= 12.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            let gap = (next_item_size - pr) as f64;
            score += 6.0 * (gap / bin_capacity as f64);
        }
        // Harmonic check: next item lands exactly on a class boundary
        if next_item_size % 10 == 0 && next_item_size <= pr {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Tightness reward: snug fit (little slack) is good
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Prefer filling older/more-loaded bins when many bins are open
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all poor fits. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; reduced late in the stream or when open
        // bins are already crowded on average.
        let mut new_bin_cost = 55.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= 15.0 * progress;
        // If mean residual across open bins is small, opening a bin is more justified.
        let mean_res_ratio = mean_residual / bin_capacity as f64;
        new_bin_cost += 25.0 * mean_res_ratio;
        // If many bins can fit, no reason to open a new one.
        if fitting_bins_count > 1 {
            new_bin_cost += 40.0;
        }
        score += new_bin_cost;
    }

    score
}

