    // A post_residual that is too small for the smallest plausible item (1..100
    // range, but conservative floor ~10) is pure dead space.
    if post_residual < 10 {
        score += 1000.0;
    } else if post_residual < 20 {
        // Near-dead space: strong nonlinear penalty
