        let tightness = item_size as f64 / (item_size as f64 + post_residual as f64);
        score -= tightness * 25.0;
    } else {
        // Perfect fill: strong reward
        score -= 60.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + 3.0 * open_bins_count as f64;
        // But if this bin is the last chance and fit is good, allow opening
        if fitting_bins_count == 1 && post_residual < 15 {
            score -= 55.0;
