        score += 40.0; // dead space penalty
    }
    // Harmonic class: residuals divisible by 10 are "clean" slots for typical item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Perfect fit is best.
    if pr == 0 {
        score -= 100.0;
    }

    // Integer-division thresholds on post_residual: how many "average items" fit afterwards.
    let avg_item = 50.0f64.max(1.0);
    let slots = (pr as f64 / avg_item).floor();
    score -= slots * 4.0;

    // Lookahead: does post_residual fit the next item? Reward if yes (keeps chain going).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // Bonus if next item fills the bin almost exactly after placement.
            let pr2 = pr - next_item_size;
            if pr2 < 5 {
                score -= 10.0;
            }
