            score += ((next_item_size - pr) as f64).min(20.0) * 0.5;
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / cap;
    score -= fill * 15.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large (leaves a useful harmonic residual) or no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Large items leave large, reusable residuals in a fresh bin: encourage.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Small items in a fresh bin waste capacity: discourage.
        if item_size <= 25 {
            score += 25.0;
        }
        // If many bins already fit the item, new bin is clearly worse.
        score += (fitting_bins_count as f64) * 8.0;
        // Early in stream, tolerate new bins slightly more (exploration).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
