    // Mean-residual coupling: if this bin's residual is far below average, it is
    // already "tight" — prefer consuming tight bins (best-fit behavior).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Prefer bins with many fitting alternatives less (keep flexible bins open).
    if fitting_bins_count > 3 {
        score += 5.0;
    }

    score
}

