    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, penalize residual quadratically.
    let early = (1.0 - progress).powi(2);
    let late = progress.powi(2);
    score += norm_pr * norm_pr * cap * (0.5 * late - 0.25 * early);

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * snug * (0.5 + late);
        } else {
            // next item cannot follow here: penalize proportionally to wasted potential
            score += 4.0 * (nxt / cap) * (0.3 + 0.7 * late);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (large post residual).
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_pr) * (0.5 + late);
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early when consolidation is cheap,
        // and more so when many bins are already open.
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 6.0 + 2.0 * open_pressure * (0.4 + 0.6 * late);
        // But if mean residual of open bins is low (they're all nearly full),
