    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else {
        // Reward tight fits: the smaller the leftover, the better.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness;
    }

    // Penalize leaving a gap that is large but just barely too small for
    // the lookahead item (creates dead space for k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can still host the lookahead item.
            score -= 6.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; discourage opening new bins.
    let pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 10.0 * pressure;

    // New-bin candidate handling: opening a bin is only acceptable when
    // no open bin offers a decent fit (last chance) or the fit is bad.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // forced to open a new bin
        } else if post_residual >= 10 && bin_residual - item_size >= 10 {
