            // space; mildly attractive when current bin would become tight.
            score -= 3.0;
        } else {
            score += 15.0; // don't open bins for poor fits
        }
    } else if fitting_bins_count == 1 && post_residual >= 10 {
        // Last chance: strongly prefer using this bin over opening one.
        score -= 20.0;
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow slightly more freedom to open bins;
    // late in the stream, tighten consolidation.
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * (1.0 - progress);

    score
}

