    score -= 6.0 * ((mod10 == 0.0) as i32 as f64);
    score -= 3.0 * ((mod5 == 0.0 && mod10 != 0.0) as i32 as f64);
    score -= 1.5 * ((mod3 == 0.0) as i32 as f64);
    // Penalize awkward residues (1 or 2 mod 10 are nearly dead space).
    score += 2.5 * ((mod10 == 1.0) as i32 as f64);
    score += 1.5 * ((mod10 == 2.0) as i32 as f64);

    // Integer-division threshold coupling: post_residual bucketed by quarters.
    let quarter = bin_capacity / 4;
