        score += 8.0; // tiny dead space
    } else if pr < 2 * quarter {
        score += 2.0;
    } else if pr < 3 * quarter {
        score -= 2.0; // sweet spot for future mid-size items
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
