        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 250.0;
        if post_residual as f64 > 0.4 * bin_capacity as f64 {
            score += 100.0; // large leftover means poor fit anyway
        }
    }

    // New-bin candidate handling: empty bin has large post_residual; penalize opening
    // a new bin unless the item is large or fits poorly in existing bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 500.0 - 400.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 600.0; // no alternative: must open
        } else if item_size >= 50 {
            score -= 100.0; // large items pack well fresh
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
