pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // Smooth polynomial coupling: penalize post_residual more as stream progresses
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += (0.5 + 1.5 * prog2 + 2.0 * prog3) * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits: small post_residual relative to item size
    score -= 8.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving residual that fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = ((pr - nx) / cap).min(1.0);
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 4.0 * ((nx - pr) / cap);
        }
