    // Dead space penalty: residuals too small to fit typical items
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score += 3.0 * (0.25 - dead) * 4.0 * progress;

    // Prefer denser bins when many bins are open
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Deviation from mean residual: prefer bins closer to mean early, larger late
    let dev = (pr - mean_residual).abs() / cap;
    score += (2.0 - 4.0 * progress) * dev;

    score
}

