    } else if fill >= 0.5 {
        score -= 5.0;
    } else if fill >= 0.25 {
        score += 2.0;
    } else {
        score += 6.0; // avoid scattering into nearly-empty bins
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
