    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: small unusable gaps (below min item size 10)
    // are worthless; penalize them heavily on top of their intrinsic score.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Usable-but-tight gaps: mildly reward leaving space that can still fit
    // small future items, but only if the lookahead item can use it.
    if post_residual >= 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // lookahead fits here too: good chaining
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += (post_residual as f64) * 0.5; // gap likely wasted
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin offers a decent fit; make the empty bin mildly unattractive
    // so tight fits win, but keep it competitive vs. dead-space placements.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

