            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // last item: maximize fill
        score -= 100.0;
    }

    // Compare post_residual against mean residual: avoid creating outliers
    let pr = post_residual as f64;
    if pr < mean_residual * 0.3 {
        score += 50.0; // creating tiny unusable sliver
    } else if pr > mean_residual {
        score += (pr - mean_residual) * 0.2; // leaving unusually large space
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
