    // New-bin candidate: default neutral-ish score; open new bin only if
    // existing fits are poor (handled above) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 200.0 + progress * 50.0;
        // If next item is large, new bin keeps flexibility
        if next_item_size > 60 {
            score -= 30.0;
        }
    }

    score
}

