pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residuals divisible by common item
    // sizes (or small values) are more reusable; penalize "dead" classes.
    let pr = post_residual;
    if pr > 0 {
        // Residual classes: 0 (perfect) already handled by base.
        // Class 1..9: nearly dead space -> heavy penalty
