            score += 40.0;
        } else if pr <= 20 {
            score += 10.0;
        }
        // Reusability bonus: residual that is a multiple of 10 or 25
        // matches common item sizes, making it likely to be filled later.
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr % 25 == 0 {
            score -= 6.0;
        }
        // Odd residuals that cannot hold the next item are dead classes.
        if next_item_size > 0 && pr < next_item_size {
            score += 15.0 + 0.25 * (next_item_size - pr) as f64;
        } else if next_item_size > 0 && pr == next_item_size {
            // Perfect lookahead fit: strong reward (harmonic resonance)
            score -= 30.0;
        } else if next_item_size > 0 {
            // Fractional coupling: how well pr accommodates the next item
            let ratio = pr as f64 / next_item_size as f64;
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin
    // is costly, so reward using it (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
        // But if placement leaves a dead residual class, soften the reward.
        if pr > 0 && pr < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate: residual == capacity. Only prefer it when the
    // current placement would waste a lot, or bins are plentiful.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: opening a new bin costs ~half a bin on
        // average; make it attractive only when post_residual is large
        // relative to capacity (poor fit into existing bins).
        score = 55.0 + post_residual as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Progress-aware mild consolidation: early on, spreading items over
    // bins is fine; late, packing tighter matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Prefer bins whose residual is far from the mean (extreme fits)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight penalty when many bins are open: encourage closing them out
    score += 0.5 * open_bins_count as f64 * (pr as f64 / bin_capacity as f64);

    score
}

