}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1) are impossible, but tiny gaps
    // relative to typical item sizes are likely dead space.
    let dead_threshold: u32 = 12; // smallest practical item size
    if post_residual < dead_threshold {
        score += 100.0 * (dead_threshold - post_residual) as f64;
    }

    // Progressive dead-space penalty: quadratic in smallness of the gap.
    if post_residual > 0 && post_residual <= 25 {
        score += (26.0 - post_residual as f64) * (26.0 - post_residual as f64) * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward tight fits (small post residual relative to bin capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open bins pressure: penalize selecting bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only chosen when fits are poor.
        score += 150.0 + 3.0 * open_bins_count as f64;
        // If next item is large and this item would leave a big gap, allow new bin more readily.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 100.0;
        }
        // Late in the stream, opening new bins is less costly (no future to plan for).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 250.0;
    }
    // If next item cannot fit in post residual, this bin wastes potential pairing.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (they are "tighter" than typical, so closing them out is good).
    score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Mild stream-progress term: as the stream advances, prefer tighter fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

