    let resid = bin_residual as f64;
    if mean_residual > 0.0 { score += (mean_residual - resid) * 0.3; }
    score += 0.32 * (post_residual as f64 - mean_residual);
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 150.0; }
    if post_residual > 0 && post_residual < 10 { score += 75.0; }
    if post_residual >= 50 { score -= 10.0; }
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.25 * post_residual as f64;
    if post_residual > 0 && item_size > 0 {
        let waste_ratio = 1.0 - (item_size as f64 / post_residual as f64);
        if waste_ratio > 0.7 { score += 12.0 * waste_ratio; }
