    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless it would be nearly full afterwards
        let usable_waste = post_residual as f64 / bin_capacity as f64;
        score += 45.0 * (1.0 - usable_waste);
        if post_residual == 0 { score += 900.0; }
        if fitting_bins_count == 1 { score += 220.0; }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 12 { score += 320.0; }
        if open_bins_count < 4 && progress < 0.5 { score += 60.0; }
        score -= progress * 30.0;
        if fitting_bins_count <= 1 && post_residual < item_size { score += 45.0; }
        if fitting_bins_count == 0 { score -= 30.0; }
        if post_residual > 0 && post_residual < item_size.max(next_item_size) { score += 18.0; }
    }
    if post_residual > 0 && post_residual < 25 && next_item_size > post_residual {
        score += (25 - post_residual) as f64 * 2.2;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > next_item_size {
        score -= 55.0;
    }
    if post_residual as f64 >= bin_capacity as f64 * 0.5 { score -= 20.0; }
    if post_residual > 0 && next_item_size > 0 {
        let rem = post_residual - next_item_size.min(post_residual);
        if rem > 0 && rem <= 20 && next_item_size <= post_residual { score -= (20 - rem) as f64 * 3.0; }
