    if post_residual >= 15 && post_residual <= 60 && next_item_size > 0 {
        score -= 8.0 * (1.0 - ((post_residual as f64 - next_item_size as f64).abs()) / 60.0);
    }
    let score = score * 0.95 + (post_residual as f64) * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to plausibly fit future items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to the bin's current residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Penalize a brand-new empty bin unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Late in the stream, tighten up: prefer exact usage over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

