    // Exact-fit bonus: item fills bin completely.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual matches next item size closely.
            let chain_gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 30.0 * (1.0 - chain_gap / (bin_capacity as f64));
            if post_residual == next_item_size {
                score -= 50.0;
            }
        } else {
            // Dead space relative to next item: penalize unusable remainder.
            let dead = (post_residual as f64) / (next_item_size as f64).max(1.0);
            score += 25.0 * (1.0 - dead.min(1.0));
        }
    }

    // Compare against mean residual across open bins: prefer bins that
    // bring their residual toward the mean (balancing open bins).
    let dev_before = (bin_residual as f64 - mean_residual).abs();
    let dev_after = (post_residual as f64 - mean_residual).abs();
    score += 10.0 * (dev_after - dev_before).signum() * dev_after.min(50.0) / 50.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when no good chain exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when clearly better.
        score += 55.0;
        // Early in the stream, opening bins is cheaper (more future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large and unknown bins are tight, new bin helps.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 35.0;
        }
        // If many bins are open already, avoid proliferation.
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // Mild penalty for very small post_residual that wastes capacity
    // (fragmentation below the minimum item size is useless dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    }

    score
}

