    // Reward tight fits: small post_residual is good, amplify non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }
    // Reward bins whose leftover exactly or nearly fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the item
    // fits poorly everywhere else, or many bins are congested.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let congestion = (open_bins_count as f64) / (mean_residual.max(1.0) / 10.0 + 1.0);
        score += 18.0 + 0.35 * (post_residual as f64);
        // Late in the stream, opening new bins is cheaper (less future to serve).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
