        score += 0.25 * mean_residual;
        // Discourage new bin if plenty of bins fit the item.
        score += 8.0 * (fitting_bins_count as f64);
        let _ = congestion;
    } else {
        // Slight preference for filling bins that are already mostly full.
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 8.0 * fill;
        // Spread items when too many bins are open relative to remaining stream.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if open_bins_count as f64 > remaining * 0.5 {
            score += 5.0;
        }
    }

    score
}

